### `src/store.js`
(Handles the in-memory data persistence layer)

```javascript
/**
 * In-Memory Todo Store
 * @type {Array<{id: string, title: string, completed: boolean, createdAt: Date, updatedAt: Date}>}
 */
let todos = [];

const generateId = () => Math.random().toString(36).substring(2);

/**
 * Adds a new todo item to the store.
 * @param {string} title - The title of the todo.
 * @returns {Object} The created todo object.
 */
export const createTodo = (title) => {
    const id = generateId();
    const now = new Date();
    const newTodo = {
        id,
        title,
        completed: false,
        createdAt: now,
        updatedAt: now
    };
    todos.push(newTodo);
    return newTodo;
};

/**
 * Finds all todos, optionally filtered by completion status.
 * @param {boolean | null} [filterCompleted] - True for completed, false for incomplete, null for all.
 * @returns {Array<Object>} Array of matching todo objects.
 */
export const getTodos = (filterCompleted) => {
    if (filterCompleted === true) {
        return todos.filter(todo => todo.completed);
    }
    if (filterCompleted === false) {
        return todos.filter(todo => !todo.completed);
    }
    // If filter is null or undefined, return all
    return [...todos];
};

/**
 * Finds a single todo by ID.
 * @param {string} id - The ID of the todo to find.
 * @returns {Object | undefined} The found todo object, or undefined if not found.
 */
export const getTodoById = (id) => {
    return todos.find(todo => todo.id === id);
};

/**
 * Updates an existing todo item by ID.
 * @param {string} id - The ID of the todo to update.
 * @param {Partial<Object>} updates - Object containing fields to update (title, completed).
 * @returns {Object | null} The updated todo object, or null if not found.
 */
export const updateTodo = (id, updates) => {
    const index = todos.findIndex(todo => todo.id === id);
    if (index === -1) return null;

    const existingTodo = todos[index];
    const updatedTodo = {
        ...existingTodo,
        ...updates,
        updatedAt: new Date() // Always update timestamp on write
    };

    todos[index] = updatedTodo;
    return updatedTodo;
};

/**
 * Deletes a todo item by ID.
 * @param {string} id - The ID of the todo to delete.
 * @returns {boolean} True if deleted, false otherwise.
 */
export const deleteTodo = (id) => {
    const initialLength = todos.length;
    todos = todos.filter(todo => todo.id !== id);
    return todos.length < initialLength;
};

/**
 * Utility function for testing purposes: Clears the store.
 */
export const clearStore = () => {
    todos = [];
};
```

### `src/routes/todoRoutes.js`
(The core API logic and request handling)

```javascript
import express from 'express';
import * as Store from '../store.js';

const router = express.Router();

// Middleware for validation helpers
const validateTitle = (title, min = 1, max = 100) => {
    if (!title || typeof title !== 'string' || title.trim().length < min || title.trim().length > max) {
        return 'Title is required and must be a string between 1 and 100 characters.';
    }
    return null;
};

// GET /todos - list all todos (support ?completed=true/false filter)
router.get('/', (req, res, next) => {
    const completedFilter = req.query.completed === 'true';
    if (typeof completedFilter !== 'boolean' && ['true', 'false'].includes(req.query.completed)) {
        // This case should ideally not happen with proper query parsing but ensures robustness
        return res.status(400).json({ message: 'Invalid filter parameter. Use ?completed=true or ?completed=false.' });
    }

    try {
        const todos = Store.getTodos(completedFilter);
        res.status(200).json(todos);
    } catch (error) {
        next(error);
    }
});

// GET /todos/:id - get single todo
router.get('/:id', (req, res, next) => {
    const id = req.params.id;
    try {
        const todo = Store.getTodoById(id);
        if (!todo) {
            return res.status(404).json({ message: `Todo with ID ${id} not found.` });
        }
        res.status(200).json(todo);
    } catch (error) {
        next(error);
    }
});

// POST /todos - create todo
router.post('/', (req, res, next) => {
    const title = req.body?.title;

    const validationError = validateTitle(title);
    if (validationError) {
        return res.status(400).json({ message: validationError });
    }

    try {
        const newTodo = Store.createTodo(title.trim());
        res.status(201).json(newTodo);
    } catch (error) {
        next(error);
    }
});

// PUT /todos/:id - update todo
router.put('/:id', (req, res, next) => {
    const id = req.params.id;
    const updates = req.body;

    try {
        let validationError = null;

        // 1. Title Validation if provided
        if (updates.title !== undefined) {
            validationError = validateTitle(updates.title);
        }

        // 2. Completed Validation
        const completedValue = updates.completed === 'true' || updates.completed === true ? true : 
                               (updates.completed === 'false' || updates.completed === false ? false : undefined);
        if (typeof completedValue !== 'boolean' && updates.completed !== undefined) {
             return res.status(400).json({ message: "Invalid value for 'completed'. Must be boolean." });
        }

        if (validationError) {
            return res.status(400).json({ message: validationError });
        }


        const updatedTodo = Store.updateTodo(id, {
            title: updates.title ? String(updates.title).trim() : undefined,
            completed: completedValue !== undefined ? completedValue : undefined
        });

        if (!updatedTodo) {
            return res.status(404).json({ message: `Todo with ID ${id} not found.` });
        }

        res.status(200).json(updatedTodo);
    } catch (error) {
        next(error);
    }
});


// DELETE /todos/:id - delete todo
router.delete('/:id', (req, res, next) => {
    const id = req.params.id;

    try {
        const wasDeleted = Store.deleteTodo(id);
        if (!wasDeleted) {
            return res.status(404).json({ message: `Todo with ID ${id} not found.` });
        }
        res.status(204).send(); // No Content on successful deletion
    } catch (error) {
        next(error);
    }
});

export default router;
```

### `src/middleware/errorHandler.js`
(Centralized error handling middleware)

```javascript
/**
 * Standard Express Error Handler Middleware
 */
const errorHandler = (err, req, res, next) => {
    console.error("🚨 API ERROR HANDLER:", err.stack);

    // Default to 500 Internal Server Error
    let statusCode = 500;
    let message = 'Internal Server Error';

    if (err.name === 'ValidationError') {
        statusCode = 400;
        message = err.message;
    } else if (err.status) {
        // Handles custom status codes set by routes/controllers
        statusCode = err.status;
        message = err.message || message;
    }

    res.status(statusCode).json({ 
        status: 'error', 
        statusCode, 
        message: message 
    });
};

export default errorHandler;
```

### `server.js`
(Entry point and application setup)

```javascript
import express from 'express';
import cors from 'cors';
import todoRoutes from './src/routes/todoRoutes.js';
import errorHandler from './src/middleware/errorHandler.js';

// Initialize App
const app = express();

// --- Global Middleware Setup ---
// 1. CORS enabled for all origins (Requirement 7)
app.use(cors({
    origin: '*' // Allows all origins as requested
}));

// 2. Body parsing (Requirement 8 - JSON everywhere)
app.use(express.json());


// --- API Routes Setup ---
app.get('/', (req, res) => {
    res.status(200).json({ message: "Welcome to the Todo List API! Use /todos endpoint." });
});

// Attach the main todo routes
app.use('/todos', todoRoutes);


// --- Error Handling Middleware (Must be last) ---
// This catches all errors passed via next(error) or thrown anywhere else
app.use(errorHandler);

// Export the app instance for testing purposes (Requirement 9)
export { app }; 

// Start the actual server only if this file is run directly
if (process.env.NODE_ENV !== 'test') {
    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
        console.log(`✅ Server running on port ${PORT}`);
        console.log('Endpoints available:');
        console.log(` - GET /todos?completed=...`);
        console.log(` - POST /todos`);
    });
}
