import supertest from 'supertest';
import { app } from '../server.js';
import * as Store from '../src/store.js';

// Ensure the store is clean before running tests
beforeAll(() => {
    Store.clearStore();
});

// Clear the store after each test to ensure isolation
afterEach(() => {
    Store.clearStore();
});

describe('Todo API Endpoints Test Suite', () => {

    let createdId1, createdId2;

    // --- Test Data Setup ---
    it('should initialize and handle basic GET /todos endpoint', async () => {
        const response = await supertest(app)
            .get('/todos')
            .expect(200);

        expect(Array.isArray(response.body)).toBe(true);
        expect(response.body).toHaveLength(0);
    });

    // --- POST /todos Tests (Create) ---
    it('should successfully create a new todo item', async () => {
        const response = await supertest(app)
            .post('/todos')
            .send({ title: 'Buy groceries' })
            .expect(201);

        expect(response.body).toHaveProperty('id');
        expect(response.body).toHaveProperty('title', 'Buy groceries');
        expect(response.body).toHaveProperty('completed', false);
        // Check timestamps existence (optional but good practice)
        expect(typeof response.body.createdAt).toBe('object');
    });

    it('should return 400 error if title is missing in POST', async () => {
        const response = await supertest(app)
            .post('/todos')
            .send({ title: '' }) // Empty title
            .expect(400);

        expect(response.body).toHaveProperty('message');
    });

    it('should return 400 error if title exceeds max length in POST', async () => {
        const longTitle = 'a'.repeat(101);
        const response = await supertest(app)
            .post('/todos')
            .send({ title: longTitle })
            .expect(400);

        expect(response.body).toHaveProperty('message');
    });


    // --- GET /todos Tests (List & Filter) ---
    it('should list all todos when no filter is applied', async () => {
        // Create two items to test listing
        await supertest(app).post('/todos').send({ title: 'Task 1' });
        createdId1 = (await supertest(app).get('/todos')).body[0].id;

        await supertest(app).put(`/todos/${createdId1}`).send({ completed: true }); // Mark as done
        createdId2 = await supertest(app).post('/todos').send({ title: 'Task 2' }).expect(201);


        const response = await supertest(app)
            .get('/todos')
            .expect(200);

        expect(response.body).toHaveLength(2); // Should return both
    });

    it('should filter and only list completed todos when ?completed=true', async () => {
        // Set up one done and one pending task
        await supertest(app).post('/todos').send({ title: 'Pending Task' }); 
        const tempId = (await supertest(app).get('/todos')).body[0].id;

        // Update the temporary task to completed status using a separate API call for reliable setup
        await supertest(app)
            .put(`/todos/${tempId}`)
            .send({ title: 'Pending Task', completed: true })
            .expect(200);

        // Now, list only completed tasks
        const response = await supertest(app)
            .get('/todos?completed=true')
            .expect(200);

        expect(response.body).toHaveLength(1); // Only the updated task should show up
    });

    it('should filter and only list pending todos when ?completed=false', async () => {
         // Create one done and one pending task
        await supertest(app).put('/todos/fakeid').send({ completed: true }); // Placeholder update for initial setup
        createdId1 = await supertest(app).post('/todos').send({ title: 'Pending Task' }).expect(201);

        // List only incomplete tasks
        const response = await supertest(app)
            .get('/todos?completed=false')
            .expect(200);

        expect(response.body).toHaveLength(1); 
    });


    // --- GET /todos/:id Tests (Single Item) ---
    it('should fetch a single todo by ID', async () => {
        const response = await supertest(app)
            .post('/todos')
            .send({ title: 'Fetch Test' })
            .expect(201);

        createdId1 = response.body.id;

        await supertest(app)
            .get(`/todos/${createdId1}`)
            .expect(200);
    });

    it('should return 404 if a todo ID does not exist', async () => {
        const response = await supertest(app)
            .get('/todos/non-existent-id-xyz')
            .expect(404);

        expect(response.body).toHaveProperty('message');
    });


    // --- PUT /todos/:id Tests (Update) ---
    it('should update the title and completion status of an existing todo', async () => {
        const response = await supertest(app)
            .post('/todos')
            .send({ title: 'Original Title' })
            .expect(201);

        createdId1 = response.body.id;

        const updateData = { 
            title: 'Updated Awesome Title', 
            completed: true 
        };

        await supertest(app)
            .put(`/todos/${createdId1}`)
            .send(updateData)
            .expect(200);

        // Verify the update by fetching it again
        const verifyResponse = await supertest(app)
             .get(`/todos/${createdId1}`)
             .expect(200);

        expect(verifyResponse.body.title).toBe('Updated Awesome Title');
        expect(verifyResponse.body.completed).toBe(true);
    });

    it('should handle partial update (only updating status)', async () => {
         const response = await supertest(app)
            .post('/todos')
            .send({ title: 'Original Task' })
            .expect(201);
        createdId1 = response.body.id;

        // Only update completion status
        await supertest(app)
            .put(`/todos/${createdId1}`)
            .send({ completed: true })
            .expect(200);
    });


    it('should return 400 error if title is invalid during PUT', async () => {
        const response = await supertest(app)
            .post('/todos')
            .send({ title: 'Valid Task' })
            .expect(201);
        createdId1 = response.body.id;

        const updateData = { title: '' }; // Invalid title
        await supertest(app)
            .put(`/todos/${createdId1}`)
            .send(updateData)
            .expect(400);
    });


    // --- DELETE /todos/:id Tests (Delete) ---
    it('should successfully delete an existing todo', async () => {
        await supertest(app)
            .post('/todos')
            .send({ title: 'Deletable Task' })
            .expect(201);
        createdId1 = (await supertest(app).get('/todos')).body[0].id;

        // DELETE call
        await supertest(app)
            .delete(`/todos/${createdId1}`)
            .expect(204); // No Content

        // Verify deletion
        await supertest(app)
            .get(`/todos/${createdId1}`)
            .expect(404); 
    });

    it('should return 404 if trying to delete a non-existent todo', async () => {
        await supertest(app)
            .delete('/todos/definitely-not-there')
            .expect(404);
    });
});
